## Trích xuất kết quả


::: {.cell}

```{.r .cell-code}
if (has_metafor) {
  model_summary <- tibble(
    model = c("Fixed-effect", "Random-effects"),
    pooled_effect = c(
      as.numeric(fixed_model$b),
      as.numeric(random_model$b)
    ),
    se = c(
      fixed_model$se,
      random_model$se
    ),
    ci_lower = c(
      fixed_model$ci.lb,
      random_model$ci.lb
    ),
    ci_upper = c(
      fixed_model$ci.ub,
      random_model$ci.ub
    )
  )

  model_summary
}
```

