## Random-effects model theo region


::: {.cell}

```{.r .cell-code}
if (has_metafor) {
  subgroup_models <- meta_data |>
    group_by(region) |>
    group_modify(
      ~ {
        model <- metafor::rma(
          yi = effect_size,
          vi = variance,
          data = .x,
          method = "REML"
        )

        tibble(
          pooled_effect = as.numeric(model$b),
          ci_lower = model$ci.lb,
          ci_upper = model$ci.ub,
          i_squared = model$I2
        )
      }
    ) |>
    ungroup()

  subgroup_models
}
```

